# 查看最近的请求日志，找耗时长的操作
ls -lt /root/.nanobot/request_logs/ 2>/dev/null | head -5 && echo "---" && for f in $(ls -t /root/.nanobot/request_logs/*.json 2>/dev/null | head -3); do echo "=== $f ===" && python3 -c "
import json, sys
with open('$f') as fh:
    d = json.load(fh)
    # look for duration, elapsed, or timing info
    if isinstance(d, dict):
        for k in ['duration','elapsed','time','latency','total_time']:
            if k in d: print(f'{k}: {d[k]}')
        # print keys to understand structure
        print('keys:', list(d.keys())[:15])
    elif isinstance(d, list):
        print(f'list of {len(d)} items')
        if d: print('first keys:', list(d[0].keys())[:15] if isinstance(d[0], dict) else type(d[0]))
" 2>/dev/null; done
